//! Shared helpers and compile-time configuration for procedural macros.

/// Compile-time configuration constants generated by `build.rs`.
///
/// These values are read from the workspace `.env` (or process environment)
/// at build time. They are intended exclusively for use inside procedural
/// macros and other build tooling.
///
/// Do not use this module from runtime application code.
pub mod build_config {
    include!(concat!(env!("OUT_DIR"), "/build_config.rs"));
}
pub mod factory;
pub mod resource;
pub mod validator;

pub use validator::*;
